# owner: platform
import unittest

from hourglass.timesheet import timesheet_rows
from hourglass.models import Shift, Span
from hourglass.errors import ProjectError


def shift(worker, day, start, end):
    return Shift(worker, day, Span(start, end))


class TimesheetRowsTests(unittest.TestCase):
    def test_totals_per_worker(self):
        rows = timesheet_rows([
            shift("Ana", "mon", 540, 810),
            shift("Ana", "tue", 540, 600)
        ])
        self.assertEqual(
            rows, ["Ana: 2 shifts, 5.5 hours"]
        )

    def test_busiest_first(self):
        rows = timesheet_rows([
            shift("Bo", "mon", 540, 600),
            shift("Cy", "mon", 540, 840),
            shift("Al", "tue", 540, 600)
        ])
        names = [row.split(":")[0] for row in rows]
        self.assertEqual(names, ["Cy", "Al", "Bo"])

    def test_empty_list_raises(self):
        with self.assertRaises(ProjectError):
            timesheet_rows([])

    def test_blank_worker_raises(self):
        with self.assertRaises(ProjectError):
            timesheet_rows([shift("  ", "mon", 0, 60)])


if __name__ == "__main__":
    unittest.main()
